targets.expr:
sum by (status) (
  kube_node_role{role="control-plane"}
  * on(node) group_right()
  kube_node_status_condition{condition="Ready", status="true"}
)

sum (
  kube_node_role{role="control-plane"}
  * on(node) group_right()
  kube_node_status_condition{condition="Ready", status=~"false|unknown"}
)

sum by (status) (
  kube_node_role{role="control-plane"}
  * on(node) group_right()
  kube_node_status_condition{condition="Ready", status="unknown"}
)

sum by (status) (
  (
    kube_node_labels{label_ten1010_io_gpu_mode=""}
    unless on(node) kube_node_role{role="control-plane"}
  )
  * on(node) group_right()
  kube_node_status_condition{condition="Ready", status="unknown"}
)

sum by (status) (
  kube_node_labels{label_ten1010_io_gpu_mode!=""}
  * on(node) group_right()
  kube_node_status_condition{condition="Ready", status="unknown"}
)

sum(rate(request_operation_total{
  node="",
  namespace!~"^(|aipub.*|coaster|efk|prometheus|linkerd|ingress-nginx|keycloak|kube-flannel|kube-system|kube-public|s3-harbor|project-controller|harbor|kube-node-lease)$", 
  operation="", 
  deployment="", 
  pod=""
}[$__range])) by (namespace)
or
sum(kube_namespace_created{
  namespace!~"^$|aipub.*|coaster|efk|prometheus|linkerd|ingress-nginx|keycloak|kube-flannel|kube-system|kube-public|s3-harbor|project-controller|harbor|kube-node-lease"
}) by (namespace) * 0

sum by (node) (
  kube_pod_labels{label_operation_aipub_ten1010_io_owner!=""}
  * on(pod) group_left(node) kube_pod_info{node!=""}
)
or
sum by (node) (kube_node_info{node!=""}) * 0

sum by (namespace) (
   kube_pod_labels{label_operation_aipub_ten1010_io_owner!=""}
   * on(pod, namespace) group_left(node)
   kube_pod_info{node!=""}
)
or
sum(kube_namespace_created{}) by (namespace) * 0
